'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var nanmmax = require( './../lib' );

// TESTS //

tape( 'main export is a function', function test( t ) {
    t.ok( true, __filename );
    t.strictEqual( typeof nanmmax, 'function', 'main export is a function' );
    t.end();
});

tape( 'the function throws an error if not provided a positive integer', function test( t ) {
    var values;
    var i;

    values = [
        '5',
        -5,
        0,
        3.14,
        true,
        false,
        null,
        void 0,
        NaN,
        [],
        {},
        function noop() {}
    ];

    for ( i = 0; i < values.length; i++ ) {
        t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
    }
    t.end();

    function badValue( value ) {
        return function badValue() {
            nanmmax( value );
        };
    }
});

tape( 'the function returns an accumulator function', function test( t ) {
    t.equal( typeof nanmmax( 3 ), 'function', 'returns a function' );
    t.end();
});

tape( 'the accumulator function computes a moving maximum, ignoring NaN values', function test( t ) {
    var expected;
    var actual;
    var data;
    var acc;
    var N;
    var i;

    data = [ 2.0, NaN, -5.0, 3.0, NaN, 4.0, 5.0, -2.0, 3.0, 1.0 ];
    N = 3;

    expected = [
        2.0,  // 2.0
        2.0,  // 2.0, NaN
        2.0,  // 2.0, NaN, -5.0
        3.0,  // NaN, -5.0, 3.0
        3.0,  // -5.0, 3.0, NaN
        4.0,  // 3.0, NaN, 4.0
        5.0,  // NaN, 4.0, 5.0
        5.0,  // 4.0, 5.0, -2.0
        3.0,  // 5.0, -2.0, 3.0
        3.0   // -2.0, 3.0, 1.0
    ];

    acc = nanmmax( N );

    for ( i = 0; i < data.length; i++ ) {
        actual = acc( data[ i ] );
        t.equal( actual, expected[ i ], 'returns expected value for window '+N+', index '+i );
    }
    t.end();
});

tape( 'if provided NaN values only, the accumulator function returns null', function test( t ) {
    var acc;
    var v;
    var i;

    acc = nanmmax( 3 );
    
    for ( i = 0; i < 10; i++ ) {
        v = acc( NaN );
        t.equal( v, null, 'returns null' );
    }
    t.end();
});

tape( 'if not provided an input value, the accumulator function returns the current maximum', function test( t ) {
    var acc = nanmmax( 3 );
    var v;

    v = acc();
    t.equal( v, null, 'returns null' );

    v = acc( 3.0 );
    t.equal( v, 3.0, 'returns expected value' );

    v = acc( NaN );
    t.equal( v, 3.0, 'returns expected value' );

    v = acc();
    t.equal( v, 3.0, 'returns expected value' );

    t.end();
}); 